      background: linear-gradient(135deg, #7638FA 0%, #FF7A00 100%);
    }

    /* Button hover glow */
    .btn-glow {
      position: relative;
      overflow: hidden;
      transition: all 0.3s ease;
    }
    .btn-glow::before {
      content: '';
      position: absolute;
      inset: -2px;
      background: linear-gradient(135deg, #7638FA, #FF7A00);
      border-radius: inherit;
      z-index: -1;
